sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    // Variável do gráfico renomeada
    var chartResultPrim = null;

    $scope.anoSelecionadoResultPrim = "";
    $scope.exibirGraficoResultPrim = false;

    var coresResultPrim = {
        apurado: '#a7b9e8',
        meta: '#4b77bf'
    };

    function carregarDadosResultPrimFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoResultPrim || ""
        };
        $scope.server.get(filtros).then(function(response) {
            // Lendo a variável renomeada no Server Script
            var dados = response.data.dadosGraficoResultPrim || [];
            var anosDisponiveis = response.data.anos || [];

            $timeout(function() {
                montarGraficoResultPrim(dados, anosDisponiveis);
            });
        });
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoResultPrim = ano;
        carregarDadosResultPrimFiltrado();
    });

    carregarDadosResultPrimFiltrado();

    function montarGraficoResultPrim(listaDados, anosDisponiveis) {

        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        // Limpeza usando a nova variável de gráfico
        if (anosPresentes.length === 0) {
            if (chartResultPrim) {
                chartResultPrim.destroy();
                chartResultPrim = null;
            }
            $scope.exibirGraficoResultPrim = false;
            return;
        }
        $scope.exibirGraficoResultPrim = true;

        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.apurado) : null;
        });
        var dadosMeta = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.meta) : null;
        });

        // ------------------------
        // ESCALA DINÂMICA (mil, mi, bi)
        // ------------------------
        var todosValores = dadosApurado.concat(dadosMeta).filter(function(v) {
            return v !== null && !isNaN(v);
        });

        var maxAbs = 0;
        if (todosValores.length > 0) {
            var maxValCalc = Math.max.apply(null, todosValores);
            var minValCalc = Math.min.apply(null, todosValores);
            maxAbs = Math.max(Math.abs(maxValCalc), Math.abs(minValCalc));
        }

        var unidadeEscala = '';
        var divisorEscala = 1;

        if (maxAbs >= 1e9) {
            unidadeEscala = ' bi';
            divisorEscala = 1e9;
        } else if (maxAbs >= 1e6) {
            unidadeEscala = ' mi';
            divisorEscala = 1e6;
        } else if (maxAbs >= 1e3) {
            unidadeEscala = ' mil';
            divisorEscala = 1e3;
        }

        // ------------------------
        // ESCALA Y
        // ------------------------
        var maxVal = todosValores.length > 0 ? Math.max.apply(null, todosValores) : 100;
        var minVal = todosValores.length > 0 ? Math.min.apply(null, todosValores) : 0;

        var PADDING_FIXO = 100; // Atenção: Ajustar se os valores forem muito pequenos pós divisão, mas aqui é valor bruto
        var scaleMax;
        var scaleMin;

        if (maxVal === 0 && minVal === 0) {
            scaleMax = 10;
            scaleMin = -10;
        } else {
            scaleMax = maxVal + PADDING_FIXO;
            scaleMin = minVal - PADDING_FIXO;

            if (minVal >= 0 && scaleMin < 0) {
                scaleMin = 0;
            }
        }

        var desiredType = 'bar';

        var datasets = [{
            label: 'Valor Apurado',
            data: dadosApurado,
            backgroundColor: coresResultPrim.apurado,
            borderColor: coresResultPrim.apurado,
            borderWidth: 1
        },{
            label: 'Meta',
            data: dadosMeta,
            backgroundColor: coresResultPrim.meta,
            borderColor: coresResultPrim.meta,
            borderWidth: 1
        }];

        datasets.forEach(function(ds, index){
            ds.pointStyle = 'rect';
            ds.pointBackgroundColor = ds.backgroundColor;
            ds.pointBorderColor = ds.backgroundColor;
            ds.pointBorderWidth = 0;
        });

        // ATENÇÃO: Pegando o novo ID
        var ctx = document.getElementById('graficoResultPrim').getContext('2d');

        if (chartResultPrim) {
            chartResultPrim.destroy();
            chartResultPrim = null;
        }

        chartResultPrim = new Chart(ctx, {
            type: desiredType,
            data: {
                labels: anosPresentes,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: {
                    duration: 700,
                    easing: 'easeInOutQuad'
                },
                scales: {
                    x: {
                        display: true,
                        offset: true,
                        grid: {
                            offset: true
                        },
                        ticks: {
                            color: '#0E2B69',
                            font: {
                                size: 16,
                                weight: 800,
                                family: 'Roboto Flex, sans-serif',
                                lineHeight: 1.8
                            },
                            padding: 6,
                            maxRotation: 0,
                            autoSkip: false
                        }
                    },
                    y: {
                        display: true,
                        position: 'right',
                        min: scaleMin, // Se quiser usar a escala calculada
                        max: scaleMax, // Se quiser usar a escala calculada
                        // Se preferir automático, remova min/max
                        ticks: {
                            callback: function(value) {
                                var scaled = value / divisorEscala;
                                return scaled.toLocaleString('pt-BR', {
                                    minimumFractionDigits: 2,
                                    maximumFractionDigits: 2
                                }) + unidadeEscala;
                            },
                            color: '#0E2B69',
                            font: {
                                size: 14,
                                family: 'Roboto Flex, sans-serif'
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top',
                        labels: {
                            usePointStyle: true
                        }
                    },
                    tooltip: {
                        enabled: true,
                        callbacks: {
                            label: function(context) {
                                var raw = context.raw || 0;
                                var scaled = raw / divisorEscala;
                                return context.dataset.label + ': ' +
                                    scaled.toLocaleString('pt-BR', {
                                        minimumFractionDigits: 2,
                                        maximumFractionDigits: 2
                                    }) + unidadeEscala;
                            }
                        }
                    },
                    datalabels: {
                        anchor: 'end',
                        align: function(context) {
                            return context.raw < 0 ? 'bottom' : 'top';
                        },
                        formatter: function(value) {
                            if (value === null) return '';
                            var scaled = value / divisorEscala;
                            return scaled.toLocaleString('pt-BR', {
                                minimumFractionDigits: 2,
                                maximumFractionDigits: 2
                            }) + unidadeEscala;
                        },
                        color: '#000',
                        font: { weight: 'bold' }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    // Array de retorno renomeado
    data.dadosGraficoResultPrim = [];
    data.anos = [];

    var anoFiltro = input.ano || "";

    // --- 1. Busca e Popula os Anos Disponíveis ---
    var grAnos = new GlideAggregate('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
    grAnos.addAggregate('COUNT');
    grAnos.groupBy('u_ano');
    grAnos.orderBy('u_ano');
    grAnos.query();

    while (grAnos.next()) {
        data.anos.push(grAnos.getValue('u_ano').toString());
    }
    data.anos = Array.from(new Set(data.anos));
    data.anos.sort();

    // --- 2. Busca os Dados (ResultPrim) ---
    var grResultPrim = new GlideRecord('x_sded9_portal_t_0_programa_de_ajuste_fiscal');

    if (anoFiltro !== "" && anoFiltro.toLowerCase() !== "todos") {
        grResultPrim.addQuery('u_ano', anoFiltro);
    }

    grResultPrim.orderBy('u_ano');
    grResultPrim.query();

    var listaResultPrim = [];
    while (grResultPrim.next()) {
        var ano = grResultPrim.getValue('u_ano').toString();
        // Campos mantidos conforme seu código
        var apurado = grResultPrim.getValue('valor_apurado_arrecadacao_propria') || '0';
        var meta = grResultPrim.getValue('meta_arrecadacao_propria') || '0';

        listaResultPrim.push({
            ano: ano,
            apurado: apurado,
            meta: meta
        });
    }

    data.dadosGraficoResultPrim = listaResultPrim;
})();
